import{_ as l,o as t,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"CDS Squid: Telemetry","description":"","frontmatter":{"title":"CDS Squid: Telemetry","date":"2023-07-20T00:00:00.000Z","updated":"2023-07-21T00:00:00.000Z","tags":["Ceph","分布式存储","遥测","蓝店","崩溃报告","仪表板","配置分析","用户反馈"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/CDS_Squid_-_Telemetry.md","filePath":"posts/2023/CDS_Squid_-_Telemetry.md","lastUpdated":1780459816000}'),a={name:"posts/2023/CDS_Squid_-_Telemetry.md"};function o(s,e,p,_,n,d){return t(),i("div",null,[...e[0]||(e[0]=[r('<h2 id="改进后的中文总结内容" tabindex="-1">改进后的中文总结内容 <a class="header-anchor" href="#改进后的中文总结内容" aria-label="Permalink to &quot;改进后的中文总结内容&quot;">​</a></h2><p>在本次CDS Squid Telemetry会议中，CBS团队针对Ceph分布式存储系统的遥测功能进行了深入讨论。会议主要围绕以下几个方面展开：</p><ol><li><p><strong>集群内容分析与遥测工具</strong>：讨论了如何通过遥测工具收集集群内容的摘要信息，如对象大小分布、BlueStore碎片化信息等，以支持去重和分块等功能的决策。决定开发一个工具，使用liberators库来爬取目标池或集群，生成内容摘要，并通过遥测系统上报。</p></li><li><p><strong>仪表板功能使用分析</strong>：探讨了在仪表板中收集用户访问数据的可能性，以便优化仪表板的用户体验。决定设计一个方案来收集和分析用户在仪表板上的行为，同时确保数据的安全性和隐私性。</p></li><li><p><strong>配置分析与用户反馈</strong>：讨论了如何通过Telemetry数据来分析集群配置，提供配置建议，减少配置错误。决定确定哪些配置数据可以安全地收集和分析，以及如何将分析结果反馈给用户。</p></li><li><p><strong>崩溃报告优化</strong>：讨论了如何优化崩溃报告的分组算法，减少重复和噪声。决定进一步研究和优化崩溃签名的生成算法，特别是对于包含RocksDB帧的崩溃报告。</p></li></ol><p>会议还讨论了定期发布Telemetry项目新闻通讯的可能性，包括集群报告的数量和大小等信息。</p><p>此外，会议还涉及以下内容：</p><ul><li>开发集群内容分析工具，并集成到Telemetry系统中。</li><li>设计并实现仪表板使用数据的收集和分析系统。</li><li>确定并收集必要的配置数据，开发配置分析和反馈系统。</li><li>优化崩溃报告的分组算法，减少重复和噪声。</li></ul><h2 id="相关标签" tabindex="-1">相关标签 <a class="header-anchor" href="#相关标签" aria-label="Permalink to &quot;相关标签&quot;">​</a></h2><ul><li>Ceph</li><li>分布式存储</li><li>遥测</li><li>蓝店</li><li>崩溃报告</li><li>仪表板</li><li>配置分析</li><li>用户反馈</li></ul>',8)])])}const S=l(a,[["render",o]]);export{m as __pageData,S as default};
